    renderEnhancedTransactionsTable() {
        const tbody = document.querySelector('#transactions-table tbody');
        if (!tbody || !this.transactions) return;

        // Use backend-computed running balances directly
        const balances = this.runningBalances || null;

        tbody.innerHTML = this.transactions.map(transaction => {
            const account = this.accounts?.find(a => a.id === transaction.accountId);
            return renderTransactionRow(transaction, {
                variant: 'ledger',
                accounts: this.accounts,
                categories: this.categories,
                currency: transaction.accountCurrency || account?.currency || this.getPrimaryCurrency(),
                formatCurrency: (amount, currency) => this.formatCurrency(amount, currency),
                formatDate: (date) => this.formatDate(date),
                balance: balances && balances[transaction.id] !== undefined ? parseFloat(balances[transaction.id]) : undefined,
                sharedStatus: this.sharedTransactionStatuses?.[transaction.id],
                attachmentCount: this.attachmentCounts?.[transaction.id],
                selected: this.transactionsModule.selectedTransactions?.has(transaction.id),
                tagsHtml: this.renderTransactionTags(transaction.id),
                tagIds: this.getTransactionTagIds(transaction.id),
            });
        }).join('');

        this.recoverStaleAccounts();
    }

    /**
     * Rows referencing an account id the cached list doesn't have mean the list
     * is stale, not that the account is gone. Restoring a backup reassigns
     * every account id, so any page still open — or a second tab — keeps the
     * old ones and renders the whole ledger as "Unknown Account" with nothing
     * in the console to explain it (#333). Refetch once and redraw.
     */
    async recoverStaleAccounts() {
        if (this._recoveringAccounts || this._accountRecoveryExhausted) return;

        const known = new Set((this.accounts || []).map(a => a.id));
        const isMissing = t => t.accountId != null && !known.has(t.accountId);
        if (!(this.transactions || []).some(isMissing)) return;

        this._recoveringAccounts = true;
        try {
            const data = await apiFetch('/apps/budget/api/accounts').catch(() => null);
            if (!Array.isArray(data)) return;

            this.accounts = data;
            this.populateAccountDropdowns();

            // If a refetch still can't place those rows the account really is
            // gone, so stop trying — redrawing would just loop.
            const refreshed = new Set(data.map(a => a.id));
            if ((this.transactions || []).some(t => t.accountId != null && !refreshed.has(t.accountId))) {
                this._accountRecoveryExhausted = true;
                return;
            }
            this.renderEnhancedTransactionsTable();
        } catch (error) {
            console.error('Failed to refresh a stale account list:', error);
        } finally {
            this._recoveringAccounts = false;
        }
    }

    /**
     * Render tags for a transaction
     */
    renderTransactionTags(transactionId) {
        // Ensure transactionTags is initialized
        if (!this.transactionTags) {
            this.transactionTags = {};
        }

        const tags = this.transactionTags[transactionId];

        if (!tags || tags.length === 0) {
            return '<span style="color: var(--color-text-maxcontrast); font-size: 11px;">-</span>';
        }

        return tags.map(tag => `
            <span class="tag-chip"
                  style="display: inline-block; background-color: ${dom.escapeHtml(tag.color)}; color: white;
                         padding: 2px 6px; border-radius: 10px; font-size: 10px; line-height: 14px; margin: 0 2px 2px 0;
                         vertical-align: middle;"
                  title="${dom.escapeHtml(tag.name)}">
                ${dom.escapeHtml(tag.name)}
            </span>
        `).join('');
    }

