    parseColumnVisibility(settingValue) {
        const defaults = {
            date: true,
            description: true,
            vendor: true,
            category: true,
            tags: true,
            amount: true,
            balance: true,
            account: true
        };

        if (!settingValue) return defaults;

        try {
            return Object.assign({}, defaults, JSON.parse(settingValue));
        } catch (e) {
            console.error('Failed to parse column visibility settings', e);
            return defaults;
        }
    }

